package config

import (
	"github.com/crossplane/upjet/v2/pkg/config"
)

// ExternalNameConfigs contains all external name configurations for this
// provider. Every Wiz resource gets its ID from the Wiz API (or, for the
// association and link resources, a UUID generated by the Terraform provider),
// so the external name is always the Terraform resource ID.
var ExternalNameConfigs = map[string]config.ExternalName{
	"wiz_automation_rule_aws_sns":                  config.IdentifierFromProvider,
	"wiz_automation_rule_jira_add_comment":         config.IdentifierFromProvider,
	"wiz_automation_rule_jira_create_ticket":       config.IdentifierFromProvider,
	"wiz_automation_rule_jira_transition_ticket":   config.IdentifierFromProvider,
	"wiz_automation_rule_servicenow_create_ticket": config.IdentifierFromProvider,
	"wiz_automation_rule_servicenow_update_ticket": config.IdentifierFromProvider,
	"wiz_cicd_scan_policy":                         config.IdentifierFromProvider,
	"wiz_cloud_config_rule":                        config.IdentifierFromProvider,
	"wiz_cloud_config_rule_associations":           config.IdentifierFromProvider,
	"wiz_connector_aws":                            config.IdentifierFromProvider,
	"wiz_connector_gcp":                            config.IdentifierFromProvider,
	"wiz_control":                                  config.IdentifierFromProvider,
	"wiz_control_associations":                     config.IdentifierFromProvider,
	"wiz_host_config_rule_associations":            config.IdentifierFromProvider,
	"wiz_integration_aws_sns":                      config.IdentifierFromProvider,
	"wiz_integration_jira":                         config.IdentifierFromProvider,
	"wiz_integration_servicenow":                   config.IdentifierFromProvider,
	"wiz_project":                                  config.IdentifierFromProvider,
	"wiz_project_cloud_account_link":               config.IdentifierFromProvider,
	"wiz_report_graph_query":                       config.IdentifierFromProvider,
	"wiz_saml_group_mapping":                       config.IdentifierFromProvider,
	"wiz_saml_idp":                                 config.IdentifierFromProvider,
	"wiz_security_framework":                       config.IdentifierFromProvider,
	"wiz_service_account":                          config.IdentifierFromProvider,
	"wiz_user":                                     config.IdentifierFromProvider,
}

// ExternalNameConfigurations applies all external name configs listed in the
// table ExternalNameConfigs.
func ExternalNameConfigurations() config.ResourceOption {
	return func(r *config.Resource) {
		if e, ok := ExternalNameConfigs[r.Name]; ok {
			r.ExternalName = e
		}
	}
}

// ExternalNameConfigured returns the list of all resources whose external name
// is configured manually.
func ExternalNameConfigured() []string {
	l := make([]string, len(ExternalNameConfigs))
	i := 0
	for name := range ExternalNameConfigs {
		// $ is added to match the exact string since the format is regex.
		l[i] = name + "$"
		i++
	}
	return l
}
